package cn.minidayz.patcher;
import android.content.pm.*;import java.io.*;import org.json.*;
/** Local deterministic workflow; never sends API calls, skips validation or edits unknown native code. */
public final class LocalAssistant {
 static JSONObject identity(Jobs j,File apk)throws Exception{JSONObject r=new JSONObject().put("sha256",FilesEx.sha(apk,j));PackageInfo p=j.ctx.getPackageManager().getPackageArchiveInfo(apk.getPath(),0);if(p!=null){r.put("package",p.packageName);if(p.versionName!=null)r.put("version",p.versionName);r.put("version_code",p.versionCode);}return r;}
 public static JSONObject correlation(Jobs j,JSONObject input,String text)throws Exception{if(text.trim().length()==0)return new JSONObject().put("status","not-supplied").put("message","未导入游戏日志，本次仅检查项目与模块").put("automatic_repair_allowed",true);JSONObject c=LogEvidence.compare(text,input);c.put("compared_to","input");String provenance=j.ctx.getSharedPreferences("local",0).getString("output_input_sha256","");if(!c.optBoolean("automatic_repair_allowed")&&j.output!=null&&j.output.isFile()&&input.getString("sha256").equals(provenance)){JSONObject output=LogEvidence.compare(text,identity(j,j.output));if(output.optBoolean("automatic_repair_allowed")){c=output;c.put("compared_to","last-output-for-current-input");}}if(c.optString("status").equals("unknown")){try{JSONObject b=new JSONObject(new String(FilesEx.read(new FileInputStream(new File(j.root,"log-association.json")),65536),"UTF-8"));String module=j.file(2).isFile()?FilesEx.sha(j.file(2),j):"";if(LogAssociation.matches(b,input.getString("sha256"),module,AiWorkspace.hash(text.getBytes("UTF-8")),"unknown"))c.put("status","user-confirmed").put("message","你已确认此日志来自当前项目；这是用户声明，不是日志自身版本证据").put("automatic_repair_allowed",true);}catch(Exception ignored){if(j.cancelled())FilesEx.check(j);}}return c;}
 public static JSONObject run(Jobs j,boolean build)throws Exception{FilesEx.require(j.file(1).isFile(),"E_INPUT_MISSING: 请先导入完整游戏APK");j.stage("local-analysis","本地分析项目、日志和模块，不调用API");JSONObject project=ProjectAnalysis.run(j),input=identity(j,j.file(1));String logs=GameLogs.text(j);JSONObject relation=correlation(j,input,logs);JSONObject r=new JSONObject().put("format","mdz-local-assistant/1").put("created_ms",System.currentTimeMillis()).put("input",input).put("log_sha256",AiWorkspace.hash(logs.getBytes("UTF-8"))).put("project",project).put("log_relation",relation).put("log_diagnosis",LogEvidence.diagnose(logs));boolean compatible=false;String moduleHash="";try{FilesEx.require(j.file(2).isFile(),"E_INPUT_MISSING: 尚未导入插件包");j.inspect();compatible=true;moduleHash=FilesEx.sha(j.file(2),j);r.put("module_sha256",moduleHash);try{r.put("features",FeatureGuide.describe(j.plan.module,j.plan.profile));}catch(Exception guideError){r.put("feature_guide_warning","插件功能说明格式不正确，兼容性检查仍单独执行");}}catch(Exception e){r.put("compatibility_error",e.getMessage());if(j.report.has("compatibility_analysis"))r.put("compatibility_analysis",j.report.getJSONObject("compatibility_analysis"));if(j.cancelled())throw e;}r.put("compatible",compatible).put("checklist",FeatureGuide.checklist(compatible,j.keyReady,relation,false));JSONObject rule=compatible?new RepairRules(j.root).eligible(input.getString("sha256"),moduleHash):null;r.put("known_repair",rule==null?JSONObject.NULL:new JSONObject().put("id",rule.getString("id")).put("entry",rule.getString("entry")).put("summary",rule.getJSONObject("proposal").optString("summary")));JSONObject gate=AutonomyDecision.decide(compatible,j.keyReady,relation.optBoolean("automatic_repair_allowed"),r.getJSONObject("log_diagnosis").getJSONArray("groups").length()>0,rule!=null);r.put("automatic_action",gate);r.put("decision",!compatible?"需要对应版本适配包":!relation.optBoolean("automatic_repair_allowed")?"日志归属不明确，停止自动修改":rule!=null?"发现可本地复用的实测修复规则":"兼容检查通过，未找到可复用修复规则");save(j,r);
 if(build){FilesEx.require(gate.getBoolean("allowed"),gate.optString("error_code")+": "+gate.optString("reason"));if(rule!=null){j.stage("local-repair","复用已实测规则，重新校验原文并备份插件");String entry=rule.getString("entry");byte[] before=AiWorkspace.current(j,entry);FilesEx.require(AiWorkspace.hash(before).equals(rule.getString("before_sha256")),"E_RULE_PREIMAGE: 规则原文指纹不符");String after=AiWorkspace.validate(rule.getJSONObject("proposal"),AiWorkspace.utf8(before));FilesEx.require(AiWorkspace.hash(after.getBytes("UTF-8")).equals(rule.getString("after_sha256")),"E_RULE_POSTIMAGE: 规则目标指纹不符");j.report.put("replay_rule",true);try{AiWorkspace.apply(j,rule.getJSONObject("proposal"),entry,input.getString("sha256"),moduleHash);}finally{j.report.remove("replay_rule");}r.put("rule_applied",rule.getString("id"));save(j,r);}j.build();r.put("module_sha256",FilesEx.sha(j.file(2),j));r.put("checklist",FeatureGuide.checklist(true,true,relation,true)).put("decision",rule==null?"已按兼容插件生成APK；未宣称修复日志中的问题":"已复用实测规则并生成APK，仍需验证本次游戏运行结果").put("output_sha256",j.report.optString("output_sha256"));save(j,r);}j.stage("local-complete",r.getString("decision"));return r;}
 public static void save(Jobs j,JSONObject r)throws Exception{File tmp=new File(j.root,"local-assistant.pending");FilesEx.write(tmp,r.toString(2).getBytes("UTF-8"));FilesEx.atomic(tmp,new File(j.root,"local-assistant.json"));}
 public static String render(JSONObject r)throws Exception{StringBuilder s=new StringBuilder(r.optString("decision"));JSONObject c=r.optJSONObject("log_relation");if(c!=null)s.append("\n日志核对：").append(c.optString("message"));JSONArray checks=r.optJSONArray("checklist");if(checks!=null){s.append("\n\n验证清单\n");for(int i=0;i<checks.length();i++){JSONObject x=checks.getJSONObject(i);s.append(x.optString("name")).append("：").append(x.optString("status")).append("\n");}}JSONObject d=r.optJSONObject("log_diagnosis");if(d!=null){s.append("\n本地错误分类\n").append(d.optString("conclusion")).append("\n");JSONArray groups=d.getJSONArray("groups");for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);s.append(g.getString("title")).append(" × ").append(g.getInt("occurrences")).append("\n").append(g.getString("suggestion")).append("\n");}}JSONArray features=r.optJSONArray("features");if(features!=null){s.append("\n插件功能与定位\n");for(int i=0;i<features.length();i++){JSONObject f=features.getJSONObject(i);s.append(f.optString("name")).append("\n").append(f.optString("description")).append("\n");JSONArray locations=f.getJSONArray("locations");for(int k=0;k<Math.min(8,locations.length());k++)s.append("  ").append(locations.getJSONObject(k).getString("entry")).append("\n");}}if(r.has("compatibility_error"))s.append("\n兼容性错误：").append(r.optString("compatibility_error"));return s.toString();}
 public static String context(Jobs j)throws Exception{File f=new File(j.root,"local-assistant.json");if(!f.isFile())return "尚未生成本地诊断";JSONObject r=new JSONObject(new String(FilesEx.read(new FileInputStream(f),1048576),"UTF-8"));if(!r.getJSONObject("input").optString("sha256").equals(FilesEx.sha(j.file(1),j)))return "本地诊断对应旧APK，请重新运行";if(r.has("module_sha256")&&(!j.file(2).isFile()||!r.getString("module_sha256").equals(FilesEx.sha(j.file(2),j))))return "插件已变化，请重新运行本地诊断";if(!r.optString("log_sha256").equals(AiWorkspace.hash(GameLogs.text(j).getBytes("UTF-8"))))return "游戏日志已变化，请重新运行本地诊断";return r.toString(2);}
}
